python3 << 'EOF'
def wrap(text, width):
    lines = []
    cur = ""
    for w in text.split():
        extra = len(w) + (1 if cur else 0)
        if len(cur) + extra > width - 1:
            # Check if we can fit more words on the current line
            if len(cur) > 0 or cur == "":
                lines.append(cur)
                cur = ""
            else:
                # First word in a new line
                cur = w
        else:
            # Can fit at least one more word on the current line
            cur += f" {w}" if cur else w
    if cur:
        lines.append(cur)
    return lines

print(wrap("aaa bbb ccc", 7))
